// =====================================================================
// Classificações de arquivos — carga do PADRÃO DO SISTEMA
// Collection: classificacoesArquivos (uma só, em 3 níveis: categoria → subcategoria → tipo)
// Rodar no mongosh / Studio 3T / Booster (IntelliShell), no banco do sistema.
// IDs FIXOS (gerados a partir do nome): rodar de novo não duplica (usa upsert).
// Totais: 3 categorias · 22 subcategorias · 150 tipos
// =====================================================================

// ---------- 1. Cria a collection (se ainda não existir) ----------
if (!db.getCollectionNames().includes("classificacoesArquivos")) {
  db.createCollection("classificacoesArquivos");
}

// ---------- 2. Índices ----------
// Listar a árvore (por nível, ativos, na ordem)
db.classificacoesArquivos.createIndex({ nivel: 1, ativo: 1, ordem: 1 }, { name: "ix_nivel_ativo_ordem" });
// Filhos de uma categoria (subcategorias)
db.classificacoesArquivos.createIndex({ categoriaId: 1, nivel: 1 }, { name: "ix_categoria_nivel" });
// Tipos de uma subcategoria: padrão (usuarioId null) + os do escritório (usuarioId do pai)
db.classificacoesArquivos.createIndex({ subcategoriaId: 1, usuarioId: 1, ativo: 1 }, { name: "ix_subcategoria_usuario_ativo" });
// Tipos criados por um escritório (tela de gestão / filtro "mostrar desativados")
db.classificacoesArquivos.createIndex({ usuarioId: 1, nivel: 1, ativo: 1 }, { name: "ix_usuario_nivel_ativo" });
// NOME ÚNICO: o mesmo escritório não cria 2 tipos com o mesmo nome (sem acento/minúsculo) na mesma subcategoria.
// Vale também para os tipos padrão (usuarioId null). nomeNormalizado é gravado pelo back (minúsculo, sem acento, espaços simples).
db.classificacoesArquivos.createIndex(
  { usuarioId: 1, subcategoriaId: 1, nomeNormalizado: 1 },
  { name: "ux_tipo_nome_por_escritorio", unique: true, partialFilterExpression: { nivel: "tipo" } }
);

