// upsert por _id: insere o que falta e atualiza nome/ordem/palavras do que já existe (não mexe em tipos de escritório)
const ops = itens.map(item => ({
  updateOne: {
    filter: { _id: item._id },
    update: { $set: item, $setOnInsert: { criadoEm: agora } },
    upsert: true
  }
}));
const resultado = db.classificacoesArquivos.bulkWrite(ops, { ordered: false });
printjson({ inseridos: resultado.upsertedCount, atualizados: resultado.modifiedCount });

// ---------- 4. Conferência ----------
printjson(db.classificacoesArquivos.aggregate([
  { $match: { padraoSistema: true } },
  { $group: { _id: "$nivel", total: { $sum: 1 } } }
]).toArray());

